  return c !== undefined && /\p{L}/u.test(c)
}
function isIdentDigit(c) {
  return c !== undefined && /\p{Nd}/u.test(c)
}
function isIdentStart(c) {
  return isLetter(c) || c === '_'
}
function isIdentPart(c) {
  return isIdentStart(c) || isIdentDigit(c)
}
function isDecimalDigit(c) {
  return c !== undefined && c >= '0' && c <= '9'
}
function isHexDigit(c) {
  return c !== undefined && /[0-9a-fA-F]/.test(c)
}
function isBinaryDigit(c) {
  return c === '0' || c === '1'
}
function isOctalDigit(c) {
  return c !== undefined && c >= '0' && c <= '7'
}
function isNumTrailing(c) {
  return c !== undefined && (isLetter(c) || isIdentDigit(c) || c >= '0' && c <= '9' || c === '_')
}

