    this.line = 1
    this.col = 1
  }

  atEnd(offset = 0) {
    return this.pos + offset >= this.chars.length
  }

  peek(offset = 0) {
    return this.chars[this.pos + offset]
  }

  // Consume the current character, updating line/col, and return it.
  advance() {
    const c = this.chars[this.pos]
