    if (c === '\n') {
      this.line++
      this.col = 1
    } else if (c === '\t') {
      this.col = Math.floor((this.col - 1) / 4) * 4 + 5
    } else {
      this.col++
    }
    return c
  }

  here() {
    return { line: this.line, col: this.col }
  }

  err(pos, reason) {
    return new ScanError(pos.line, pos.col, reason)
  }

  tokenize() {
    const tokens = []
    while (!this.atEnd()) {
      const c = this.peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        while (!this.atEnd() && this.peek() !== '\n') this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '*') {
        this.scanBlockComment()
        continue
      }
      const start = this.here()
      if (isIdentStart(c)) {
        tokens.push(this.scanIdentifier(start))
        continue
      }
      if (isDecimalDigit(c)) {
        tokens.push(this.scanNumber(start))
        continue
      }
      if (c === '"') {
        tokens.push(this.scanString(start))
        continue
      }
      if (c === 'r' && this.peek(1) === '"') {
        tokens.push(this.scanRawString(start))
        continue
      }
      const punct = this.matchPunct()
      if (punct !== null) {
        tokens.push({ line: start.line, col: start.col, kind: 'punct', text: punct })
        continue
      }
      throw this.err(start, `unexpected character ${c}`)
    }
    return tokens
  }

