    const start = this.here()
    this.advance() // '/'
    this.advance() // '*'
    let depth = 1
    while (depth > 0) {
      if (this.atEnd()) {
        throw this.err(start, 'unterminated block comment')
      }
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance()
        this.advance()
        depth++
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        depth--
