    this.advance() // opening quote
    let value = ''
    while (true) {
      if (this.atEnd()) {
        throw this.err(start, 'unterminated string')
      }
      const c = this.peek()
      if (c === '"') {
        this.advance()
        break
      }
      if (c === '\n') {
        throw this.err(this.here(), 'newline in string')
      }
      if (c === '\\') {
        const backslashPos = this.here()
        this.advance()
        if (this.atEnd()) {
          throw this.err(start, 'unterminated string')
        }
