        if (e === 'n') { this.advance(); value += '\n' }
        else if (e === 't') { this.advance(); value += '\t' }
        else if (e === 'r') { this.advance(); value += '\r' }
        else if (e === '\\') { this.advance(); value += '\\' }
        else if (e === '"') { this.advance(); value += '"' }
        else if (e === '0') { this.advance(); value += '\0' }
        else if (e === 'x') {
